create table if not exists public.campus_emergency_contacts (id uuid primary key default gen_random_uuid(), campus public.campus_location, service text not null, label text not null, phone_number text not null, extension text, availability text, priority integer not null default 0, is_active boolean not null default true, last_verified_at timestamptz, verified_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint campus_emergency_contacts_phone_not_blank check (length(trim(phone_number)) > 0));